window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e1f3abeda4f514dd"]={"versions": [{"id": "FIG-e1f3abeda4f514dd", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Rollen- und artefaktbasiertes Prozess- und Datenflussdiagramm (End-to-End Build-, Integrations- und Packaging-Pipeline).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R18-10. Das Diagramm spezifiziert die mehrstufige Erstellung von Auslieferungseinheiten für das <em>Update and Configuration Management</em> (UCM). Es bildet die Brücke zwischen klassischem Software-Engineering (Source/Binaries/Manifeste), der herstellerspezifischen Paketierung (<em>Software Package</em> für UCM) und der Flotten-/Fahrzeug-Rollout-Ebene (<em>Vehicle Package Manifest</em> via OTA-Backend).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>OEM (Original Equipment Manufacturer):</strong> Definiert Systemarchitektur, Service-Schnittstellen und Machine-Topologien; fungiert im Backend als Integrator und Kampagnen-Orchestrator.\n</li><li><strong>Developer:</strong> Zulieferer/Entwickler von Applikations-Code und Initialdaten.\n</li><li><strong>Tier 1 Integrator / Packager:</strong> Führt Binaries und Manifeste zusammen, instanziiert Prozesse, definiert Software Cluster (SWCL) und signiert Auslieferungscontainer.\n</li><li><strong>OEM Backend / Packager:</strong> Konsolidiert Software Packages mehrerer Steuergeräte/Funktionen zu Gesamtfahrzeug-Updates.\n</li></ul>\n<h5 class=\"fig-section-h5\">Artefakte &amp; Datenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Service and machine designs (ARXML):</strong> Standardisierte System- und Maschinenbeschreibungen (Network Binding, Service Interfaces, Machine Manifest).\n</li><li><strong>Source code &amp; Data (PER):</strong> Quellcode sowie persistente Initialisierungs- und Konfigurationsdaten gemäß <code>ara::per</code>.\n</li><li><strong>Executable apps &amp; Process:</strong>\n<ul class=\"fig-list\"><li><em>Source/bin</em>: Kompilierte Executables.\n</li><li><em>Data (PER)</em>: Persistenz-Dateien / Storage-Init.\n</li><li><em>Executable, service instance manifests (ARXML)</em>: Deployment- und Ausführungsmanifeste (<code>StartupConfig</code>, <code>ProcessDesign</code>, Service-Instanziierung).\n</li></ul>\n</li><li><strong>SWCL description &amp; Vendor specific extensions:</strong>\n<ul class=\"fig-list\"><li><em>SWCL description</em>: Definition des Software Clusters (logische funktionale Update-Einheit auf der Adaptive Platform).\n</li><li><em>Vendor specific extensions</em>: Plattform- oder Toolchain-spezifische Metadaten (als herstellerspezifisches Format gekennzeichnet).\n</li></ul>\n</li><li><strong>Backend Package (Signed container):</strong>\n<ul class=\"fig-list\"><li><strong>Software Package A:</strong> Enthält Executables, persistente Daten und Manifeste.\n</li><li><strong>UCM Manifest:</strong> Steuerdatei für den fahrzeugseitigen UCM (Target-Installation, Abhängigkeiten, Scripting/Hooks).\n</li><li><strong>SWCL Package manifest (ARXML):</strong> Formale, standardisierte AUTOSAR-Paketbeschreibung.\n</li><li><strong>Integrator Signature:</strong> Kryptografische Signatur zur Integritäts- und Authentizitätsprüfung (PKI-basiert).\n</li></ul>\n</li><li><strong>Vehicle Package Manifest container:</strong> Aggregierte Fahrzeug-Gesamtkonfiguration, die mehrere Einzelschnittstellen referenziert.\n</li><li><strong>Campaign orchestration:</strong> OEM-Backend-Steuerung für Rollout-Strategie, Kampagnenregeln und Fahrzeugzustandsbedingungen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Format-Differenzierung &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Standard ARXML vs. Vendor specific format:</strong> Blau markierte Entitäten (<em>Data (PER)</em>, <em>Manifests</em>, <em>UCM Manifest</em>, <em>Vendor specific extensions</em>) liegen im Software Package als plattformspezifische Binär-/Targetformate vor, während SWCL- und Design-Artefakte als standardisiertes ARXML gehalten werden.\n</li><li><strong>Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>1 … * <em>Software Packages</em> werden in das OEM-Backend überführt.\n</li><li>1 … * <em>SWCL Package Manifests</em> münden in den <em>Vehicle Package Manifest container</em>.\n</li><li>1 <em>Campaign Orchestration</em> steuert genau 1 <em>Vehicle Package Manifest container</em> aus.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Bereitstellungsprozess gliedert sich in 6 aufeinanderfolgende Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Develop SW (OEM / Developer):</strong>\n<ul class=\"fig-list\"><li>OEM stellt <em>Service and machine designs</em> bereit.\n</li><li>Entwickler implementiert Applikationslogik (<em>Source code</em>) und definiert Persistenzanforderungen (<em>Data(PER)</em>).\n</li></ul>\n</li><li><strong>Integrate SW (Tier 1 Integrator):</strong>\n<ul class=\"fig-list\"><li>Übersetzung/Build zu Binaries. Verknüpfung mit <em>Executable Manifests</em> und <em>Service Instance Manifests</em>.\n</li></ul>\n</li><li><strong>Create SW pkg (Tier 1 Integrator):</strong>\n<ul class=\"fig-list\"><li>Instanziierung des <em>Process</em>: Zuordnung von Executables zu Betriebssystemprozessen, Scheduling, Ressourcengrenzen und Service-Mappings.\n</li><li>Beistellung von <em>Vendor specific extensions</em> und der <em>SWCL description</em>.\n</li></ul>\n</li><li><strong>Integrator Packager (Tier 1):</strong>\n<ul class=\"fig-list\"><li>Transformation der Artefakte in das zielplattformkonforme Format (<em>Software Package A</em> mit UCM-Manifest).\n</li><li>Generierung des standardisierten <em>SWCL Package manifest (ARXML)</em>.\n</li><li>Signierung des Containers (<em>Integrator Signature</em>) zum Schutz der Supply-Chain-Integrität.\n</li></ul>\n</li><li><strong>OEM Packager (OEM Backend):</strong>\n<ul class=\"fig-list\"><li>Validierung der Zulieferer-Signaturen und Aufnahme von n <em>Software Packages</em> in den Backend-Repository-Katalog.\n</li></ul>\n</li><li><strong>Campaign Orchestration (OEM Integrator):</strong>\n<ul class=\"fig-list\"><li>Synthese des <em>Vehicle Package Manifest container</em> aus den jeweiligen SWCL-Manifesten und Einbettung in die OTA-Kampagnenlogik (Ausrollsequenz, Sicherheitschecks, Ziel-Fahrzeugflotten).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Manifest-Transformation:</strong> Entwickler dürfen Manifeste nicht isoliert als reine ARXML-Dateien auf dem Zielsystem erwarten. Der Packager konvertiert ARXML-Manifeste häufig in optimierte, binäre oder herstellerspezifische Zielstrukturen (blaue Markierung), die vom POSIX-Dateisystem bzw. dem Adaptive Runtime Environment effizient geladen werden können.\n</li><li><strong>UCM-Konformität (<code>ara::ucm</code>):</strong> Jedes Software-Artefakt muss zwingend als Software Package mit zugehörigem <em>UCM Manifest</em> gekapselt sein. Der UCM verarbeitet keine Roh-Binaries ohne Manifest-Metadaten (Versionierung, Abhängigkeiten, Prüfsummen).\n</li><li><strong>Persistenz-Handling (<code>ara::per</code>):</strong> Initialdaten für Key-Value-Storage oder File-Storage müssen bereits im Integrationsschritt als separate Datenartefakte deklariert und verpackt werden, damit der UCM diese während des Update-Prozesses in die applikationsspezifischen Zielpfade migrieren kann.\n</li><li><strong>Security &amp; Signaturprüfung:</strong> Die <em>Integrator Signature</em> erzwingt ein definiertes PKI-Schlüsselmanagement zwischen Tier-1 und OEM. Modifikationen an Executables oder Manifesten nach dem Packager-Schritt invalidieren die Signatur und führen im UCM zu einem Abbruch des Updates (<code>kVerificationFailed</code>).\n</li><li><strong>Cluster-Granularität:</strong> Durch die Bindung an <em>SWCL Descriptions</em> wird die funktionale Austauschbarkeit definiert. Ein Prozess kann nicht standalone gepatcht werden, wenn er Bestandteil eines übergeordneten Software Clusters ist; Updates erfolgen atomar auf Software-Cluster-Ebene.\n</li></ul>"}, {"id": "FIG-0d3538837c94ac4a", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Rollen- und artefaktbasiertes Prozess- und Datenflussdiagramm (End-to-End Build-, Integrations- und Packaging-Pipeline).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R19-03. Das Diagramm spezifiziert die mehrstufige Erstellung von Auslieferungseinheiten für das <em>Update and Configuration Management</em> (UCM). Es bildet die Brücke zwischen klassischem Software-Engineering (Source/Binaries/Manifeste), der herstellerspezifischen Paketierung (<em>Software Package</em> für UCM) und der Flotten-/Fahrzeug-Rollout-Ebene (<em>Vehicle Package Manifest</em> via OTA-Backend).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>OEM (Original Equipment Manufacturer):</strong> Definiert Systemarchitektur, Service-Schnittstellen, Machine- und SWCL-Topologien; fungiert im Backend als Integrator und Kampagnen-Orchestrator.\n</li><li><strong>Developer:</strong> Zulieferer/Entwickler von Applikations-Code und Initialdaten.\n</li><li><strong>Tier 1 Integrator / Packager:</strong> Führt Binaries und Manifeste zusammen, instanziiert Prozesse, definiert Software Cluster (SWCL) und signiert Auslieferungscontainer auf mehreren Ebenen.\n</li><li><strong>OEM Backend / Packager:</strong> Konsolidiert Software Packages mehrerer Steuergeräte/Funktionen zu Gesamtfahrzeug-Updates.\n</li></ul>\n<h5 class=\"fig-section-h5\">Artefakte &amp; Datenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Service, machine, SWCL designs (ARXML):</strong> Standardisierte System-, Maschinen- und Clusterbeschreibungen.\n</li><li><strong>Source code &amp; Data (PER):</strong> Quellcode sowie persistente Initialisierungs- und Konfigurationsdaten gemäß <code>ara::per</code>.\n</li><li><strong>Executable apps &amp; Process:</strong>\n<ul class=\"fig-list\"><li><em>Source/bin</em>: Kompilierte Executables.\n</li><li><em>Data (PER)</em>: Persistenz-Dateien / Storage-Init.\n</li><li><em>Executable, service instance manifests (ARXML)</em>: Deployment- und Ausführungsmanifeste.\n</li></ul>\n</li><li><strong>SWCL design &amp; Vendor specific extensions:</strong>\n<ul class=\"fig-list\"><li><em>SWCL design</em>: Definition des Software Clusters (logische funktionale Update-Einheit).\n</li><li><em>Vendor specific extensions</em>: Plattform- oder Toolchain-spezifische Metadaten im herstellerspezifischen Format.\n</li></ul>\n</li><li><strong>Backend Package (Signed container):</strong>\n<ul class=\"fig-list\"><li><strong>Software Package A (Signed container):</strong> Verschachtelter signierter Container, enthaltend Executables, persistente Daten, Manifeste, das herstellerspezifische <em>Software Package Manifest</em> sowie eine eigene kryptografische <em>Signature</em>.\n</li><li><strong>Software Package manifest (ARXML):</strong> Standardisierte AUTOSAR-Paketbeschreibung auf Cluster-Ebene.\n</li><li><strong>Integrator Signature:</strong> Äußere kryptografische Signatur zur Integritäts- und Authentizitätsprüfung des Gesamtpakets.\n</li></ul>\n</li><li><strong>Vehicle Package Manifest container:</strong> Aggregierte Fahrzeug-Gesamtkonfiguration, die mehrere Software Package Manifeste referenziert.\n</li><li><strong>Campaign orchestration:</strong> OEM-Backend-Steuerung für Rollout-Strategie, Kampagnenregeln und Fahrzeugzustandsbedingungen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Format-Differenzierung &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Standard ARXML vs. Vendor specific format:</strong> Blau markierte Entitäten (<em>Data (PER)</em>, <em>Manifests</em>, <em>Software Package Manifest</em>, <em>Vendor specific extensions</em>, <em>Signature</em>) liegen als plattformspezifische Binär-/Targetformate vor, während Entwurfs- und Paketmanifeste als standardisiertes ARXML gehalten werden.\n</li><li><strong>Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>1 … * <em>Software Packages</em> werden in das OEM-Backend überführt.\n</li><li>1 … * <em>Software Package manifests (ARXML)</em> münden in den <em>Vehicle Package Manifest container</em>.\n</li><li>1 <em>Campaign Orchestration</em> steuert genau 1 <em>Vehicle Package Manifest container</em> aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Prozessmodell gliedert sich in fünf sequentielle Phasen entlang der beteiligten Rollen:</p>\n<ol class=\"fig-list\"><li><strong>Bereitstellung der Systementwürfe (OEM provides):</strong> Der OEM liefert die formalen Systembeschreibungen (<em>Service, machine, SWCL designs</em>) als ARXML an Entwicklung und Integration.\n</li><li><strong>Software-Entwicklung (Developer provides):</strong> Der Applikationsentwickler implementiert Quellcode und definiert persistente Daten (<em>Data (PER)</em>).\n</li><li><strong>Software-Integration (Tier 1 Integrator):</strong>\n<ul class=\"fig-list\"><li><strong>Develop SW:</strong> Quellcode wird kompiliert (<em>Source/bin</em>), initiale Datenstrukturen werden beigelegt und um Ausführungs- sowie Service-Instanz-Manifeste ergänzt.\n</li><li><strong>Integrate SW:</strong> Prozesse werden konfiguriert; Executable, Persistenzdaten und Manifeste werden als Prozess-Artefakte konsolidiert.\n</li><li><strong>Create SW pkg:</strong> Der Integrator führt die Prozess-Artefakte mit herstellerspezifischen Erweiterungen (<em>Vendor specific extensions</em>) und dem <em>SWCL design</em> zusammen.\n</li></ul>\n</li><li><strong>Paketierung (Tier 1 Integrator / Integrator Packager):</strong>\n<ul class=\"fig-list\"><li>Erstellung des <em>Software Package A</em> als zweistufig signierter Container (<em>Signed container</em>): Das Paket kapselt Executables, Daten, Manifeste, das <em>Software Package Manifest</em> und eine eigene <em>Signature</em>.\n</li><li>Generierung des <em>Software Package manifest (ARXML)</em> aus dem <em>SWCL design</em>.\n</li><li>Gesamtsignierung (<em>Integrator Signature</em>) zum <em>Backend Package</em>.\n</li></ul>\n</li><li><strong>Backend-Konsolidierung &amp; Rollout (OEM Backend / OEM Packager / OEM Integrator):</strong>\n<ul class=\"fig-list\"><li>Das OEM-Backend nimmt mehrere signierte Software Packages entgegen.\n</li><li>Die standardisierten <em>Software Package manifests (ARXML)</em> werden in den <em>Vehicle Package Manifest container</em> überführt.\n</li><li>Die <em>Campaign orchestration</em> des OEM Integrators verknüpft Rollout-Regeln mit dem Fahrzeug-Gesamtmanifest zur Durchführung des Updates.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong> Das Diagramm spezifiziert die Schnittstellen- und Verpackungsanforderungen für AUTOSAR Adaptive UCM (<em>Update and Configuration Management</em>). Wesentlich ist die hierarchische Kapselung: Ein <em>Software Package</em> ist intern als signierter Container aufgebaut und besitzt ein plattformspezifisches <em>Software Package Manifest</em> samt Signatur sowie ein standardisiertes <em>Software Package manifest (ARXML)</em> auf Cluster-Ebene.\n</li><li><strong>Sicherheitsanforderungen:</strong> Die Lieferkette wird durch eine zweistufige kryptografische Absicherung geschützt: Die innere <em>Signature</em> sichert das konkrete Software-Paket ab, während die <em>Integrator Signature</em> den gesamten Auslieferungs-Container (<em>Backend Package</em>) schützt.\n</li><li><strong>Entwickler-Hinweise:</strong> SWCL-Designs fließen bereits ab dem OEM-Entwurf ein. Integratoren müssen sicherstellen, dass herstellerspezifische Erweiterungen und interne Paketmanifeste konsistent zu den standardisierten ARXML-Paketbeschreibungen erzeugt werden.\n</li></ul>"}, {"id": "FIG-f40f71fb67da563f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Rollen- und artefaktbasiertes Prozess- und Datenflussdiagramm (End-to-End Build-, Integrations- und Packaging-Pipeline).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R19-03. Das Diagramm spezifiziert die mehrstufige Erstellung von Auslieferungseinheiten für das <em>Update and Configuration Management</em> (UCM). Es bildet die Brücke zwischen klassischem Software-Engineering (Source/Binaries/Manifeste), der herstellerspezifischen Paketierung (<em>Software Package</em> für UCM) und der Flotten-/Fahrzeug-Rollout-Ebene (<em>Vehicle Package Manifest</em> via OTA-Backend).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Rollen</h5>\n<ul class=\"fig-list\"><li><strong>OEM (Original Equipment Manufacturer):</strong> Definiert Systemarchitektur, Service-Schnittstellen, Machine- und SWCL-Topologien; fungiert im Backend als Integrator und Kampagnen-Orchestrator.\n</li><li><strong>Developer:</strong> Zulieferer/Entwickler von Applikations-Code und Initialdaten.\n</li><li><strong>Tier 1 Integrator / Packager:</strong> Führt Binaries und Manifeste zusammen, instanziiert Prozesse, definiert Software Cluster (SWCL) und sichert Auslieferungscontainer mittels Authentication Tags ab.\n</li><li><strong>OEM Backend / Packager:</strong> Konsolidiert Software Packages mehrerer Steuergeräte/Funktionen innerhalb von Vehicle Packages zu Gesamtfahrzeug-Updates.\n</li></ul>\n<h5 class=\"fig-section-h5\">Artefakte &amp; Datenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Service, machine, SWCL designs (ARXML):</strong> Standardisierte System-, Maschinen- und Clusterbeschreibungen.\n</li><li><strong>Source code &amp; Data (PER):</strong> Quellcode sowie persistente Initialisierungs- und Konfigurationsdaten gemäß <code>ara::per</code>.\n</li><li><strong>Executable apps (Phasen Develop SW &amp; Integrate SW):</strong>\n<ul class=\"fig-list\"><li><em>Source/bin</em> bzw. <em>Executable</em>: Kompilierte ausführbare Binärdateien.\n</li><li><em>Data (PER)</em>: Persistenz-Dateien / Storage-Init.\n</li><li><em>Execution, service instance manifests (ARXML)</em>: Deployment- und Ausführungsmanifeste.\n</li></ul>\n</li><li><strong>SWCL design &amp; Vendor specific extensions:</strong>\n<ul class=\"fig-list\"><li><em>SWCL design</em>: Definition des Software Clusters (logische funktionale Update-Einheit).\n</li><li><em>Vendor specific extensions</em>: Plattform- oder Toolchain-spezifische Metadaten im herstellerspezifischen Format.\n</li></ul>\n</li><li><strong>Backend Package (Signed container):</strong>\n<ul class=\"fig-list\"><li><strong>Software Package A (Signed container):</strong> Verschachtelter Container, enthaltend Executables, persistente Daten, <em>manifests</em>, das herstellerspezifische <em>Software Package Manifest</em> sowie ein eigenes <em>Authentication tag</em>.\n</li><li><strong>Software Package manifest (ARXML):</strong> Standardisierte AUTOSAR-Paketbeschreibung auf Cluster-Ebene.\n</li><li><strong>Integrator Authentication tag:</strong> Authentifizierungs-Token zur Integritäts- und Echtheitsprüfung des gesamten Backend Packages.\n</li></ul>\n</li><li><strong>Vehicle Package:</strong> Aggregierter Auslieferungscontainer im OEM-Backend, bestehend aus dem <em>Software Package manifest (ARXML)</em> und dem <em>Vehicle Package manifest container</em>.\n</li><li><strong>Campaign orchestration:</strong> OEM-Backend-Steuerung für Rollout-Strategie, Kampagnenregeln und Fahrzeugzustandsbedingungen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Format-Differenzierung &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Standard ARXML vs. Vendor specific format:</strong> Blau markierte Entitäten (<em>Data (PER)</em>, <em>manifests</em>, <em>Software Package Manifest</em>, <em>Vendor specific extensions</em>, <em>Authentication tag</em>) liegen als plattformspezifische Binär-/Targetformate vor, während Entwurfs- und Paketmanifeste als standardisiertes ARXML gehalten werden.\n</li><li><strong>Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li>1 … * <em>Software Packages</em> werden in das OEM-Backend überführt.\n</li><li>1 … * <em>Software Package manifests (ARXML)</em> münden in das <em>Vehicle Package</em>.\n</li><li>1 <em>Campaign Orchestration</em> steuert das <em>Vehicle Package</em> (bzw. den <em>Vehicle Package manifest container</em>) aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Prozessmodell gliedert sich in fünf sequentielle Phasen entlang der beteiligten Rollen:</p>\n<ol class=\"fig-list\"><li><strong>Bereitstellung der Systementwürfe (OEM provides):</strong> Der OEM liefert die formalen Systembeschreibungen (<em>Service, machine, SWCL designs</em>) als ARXML an Entwicklung und Integration.\n</li><li><strong>Software-Entwicklung (Developer provides):</strong> Der Applikationsentwickler implementiert Quellcode und definiert persistente Daten (<em>Data (PER)</em>).\n</li><li><strong>Software-Integration (Tier 1 Integrator):</strong>\n<ul class=\"fig-list\"><li><strong>Develop SW:</strong> Quellcode wird kompiliert (<em>Source/bin</em>), initiale Datenstrukturen werden beigelegt und um Ausführungs- sowie Service-Instanz-Manifeste ergänzt.\n</li><li><strong>Integrate SW:</strong> Prozesse werden konfiguriert; Executable, Persistenzdaten und Manifeste werden als Prozess-Artefakte konsolidiert.\n</li><li><strong>Create SW pkg:</strong> Der Integrator führt die Prozess-Artefakte mit herstellerspezifischen Erweiterungen (<em>Vendor specific extensions</em>) und dem <em>SWCL design</em> zusammen.\n</li></ul>\n</li><li><strong>Paketierung (Tier 1 Integrator / Integrator Packager):</strong>\n<ul class=\"fig-list\"><li>Erstellung des <em>Software Package A</em> als zweistufig signierter Container (<em>Signed container</em>): Das Paket kapselt Executables, Daten, Manifeste, das <em>Software Package Manifest</em> und eine eigene <em>Signature</em>.\n</li><li>Generierung des <em>Software Package manifest (ARXML)</em> aus dem <em>SWCL design</em>.\n</li><li>Gesamtsignierung (<em>Integrator Signature</em>) zum <em>Backend Package</em>.\n</li></ul>\n</li><li><strong>Backend-Konsolidierung &amp; Rollout (OEM Backend / OEM Packager / OEM Integrator):</strong>\n<ul class=\"fig-list\"><li>Das OEM-Backend nimmt mehrere signierte Software Packages entgegen.\n</li><li>Die standardisierten <em>Software Package manifests (ARXML)</em> werden in den <em>Vehicle Package Manifest container</em> überführt.\n</li><li>Die <em>Campaign orchestration</em> des OEM Integrators verknüpft Rollout-Regeln mit dem Fahrzeug-Gesamtmanifest zur Durchführung des Updates.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong> Die Spezifikation regelt die genaue Strukturierung von Auslieferungseinheiten für AUTOSAR Adaptive UCM. Im Fokus steht die Verwendung von Message Authentication Codes / kryptografischen Prüfwerten (<em>Authentication tag</em> bzw. <em>Integrator Authentication tag</em>) anstelle unspezifischer Signaturen, was sowohl asymmetrische Signaturen als auch symmetrische MACs abdeckt.\n</li><li><strong>Paketierungs-Hierarchie:</strong> Im OEM-Backend wird die Auslieferung auf Gesamtfahrzeugebene formal über das <em>Vehicle Package</em> strukturiert, welches das standardisierte <em>Software Package manifest (ARXML)</em> direkt neben dem <em>Vehicle Package manifest container</em> führt.\n</li><li><strong>Entwickler- und Integrator-Hinweise:</strong> Das Manifest auf Prozess- und Service-Ebene wird als <em>Execution, service instance manifest</em> geführt. Integratoren müssen bei der Paketerstellung sicherstellen, dass die Authentifizierungsanhänge (<em>Authentication tag</em> auf Package-Ebene sowie <em>Integrator Authentication tag</em> auf Backend-Package-Ebene) konform zu den kryptografischen Profilen des Zielsystems generiert werden.\n</li></ul>"}], "trans": [{"from": "FIG-e1f3abeda4f514dd", "to": "FIG-0d3538837c94ac4a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Artefakt <strong>OEM provides</strong>: Umbenannt von <em>Service and machine designs</em> zu <em>Service, machine, SWCL designs</em>.\n</li><li>Artefakt <strong>SWCL description</strong>: Umbenannt zu <em>SWCL design</em>.\n</li><li><strong>Software Package A</strong>: Enthält nun eine zusätzliche innere Kapselung <em>Signed container</em> sowie ein <em>Software Package Manifest</em> (anstelle des zuvor unverschachtelten <em>Software Package A</em> mit <em>UCM Manifest</em>).\n</li><li><strong>Sicherheits- / Signatur-Element</strong>: Zusätzliches Element <em>Signature</em> innerhalb des <em>Software Package A (Signed container)</em> ergänzt; die äußere Container-Ebene behält die <em>Integrator Signature</em>.\n</li><li>Manifest-Benennung im Container: Umbenannt von <em>SWCL Package manifest(ARXML)</em> zu <em>Software Package manifest(ARXML)</em>.\n</li><li><strong>OEM Backend</strong>: Software Package A wird nun analog als <em>Signed container</em> geführt mit <em>Software Package Manifest</em> und <em>Signature</em> (vormals <em>UCM Manifest</em> ohne eigene innere Signatur).\n</li></ul>"}, {"from": "FIG-0d3538837c94ac4a", "to": "FIG-f40f71fb67da563f", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Artefakt <strong>Tier 1 Integrator (Spalte 4)</strong>: Box-Titel umbenannt von <em>Process</em> zu <em>Executable apps</em>.\n</li><li>Manifest-Artefakt (Spalten 3 und 4): Umbenannt von <em>Executable, service instance manifests</em> zu <em>Execution, service instance manifests</em>.\n</li><li>Innerhalb <strong>Software Package A</strong>: Beschriftung <em>Manifests</em> geändert zu kleingeschriebenem <em>manifests</em>.\n</li><li>Signatur-Terminologie: <em>Signature</em> und <em>Integrator Signature</em> wurden durchgängig durch <em>Authentication tag</em> und <em>Integrator Authentication tag</em> ersetzt.\n</li><li><strong>OEM Backend</strong>: Aggregations-Container neu als <em>Vehicle Package</em> strukturiert, welcher nun explizit das <em>Software Package manifest(ARXML)</em> neben dem <em>Vehicle Package manifest container</em> aufnimmt.\n</li></ul>"}]};
